package dev.zomboid.firstaid;
import java.util.*;
public final class DressingBoost {
 public static Object mildSlow(Object player,Object effect){Object slow=R.get(R.type("net.minecraft.world.effect.MobEffects"),"MOVEMENT_SLOWDOWN");if(!Objects.equals(R.call(effect,"getEffect"),slow)||R.yes(R.call(Assist.model(player),"isUnconscious")))return effect;int amplifier=((Number)R.call(effect,"getAmplifier")).intValue();if(amplifier<=1)return effect;return R.make("net.minecraft.world.effect.MobEffectInstance",slow,((Number)R.call(effect,"getDuration")).intValue(),1,R.yes(R.call(effect,"isAmbient")),R.yes(R.call(effect,"isVisible")),R.yes(R.call(effect,"showIcon")));}
 public static String id(Object stack){Object item=R.call(stack,"getItem");return Objects.toString(R.call(item,"getDescriptionId"),"");}
 public static boolean tactical(String id){return id.startsWith("item.lrtactical.")&&id.toLowerCase(Locale.ROOT).contains("bandage");}
 public static void applied(Object player,Object stack){if(R.yes(R.call(R.call(player,"level"),"isClientSide"))||!R.yes(R.call(player,"isAlive")))return;effect(player,"REGENERATION",200,0);if(tactical(id(stack)))effect(player,"ABSORPTION",200,0);}
 private static void effect(Object player,String type,int ticks,int level){Object instance=R.make("net.minecraft.world.effect.MobEffectInstance",R.get(R.type("net.minecraft.world.effect.MobEffects"),type),ticks,level);R.call(player,"addEffect",instance);}
 public static void tooltip(Object event){Object stack=R.call(event,"getItemStack");String id=id(stack);boolean tactical=tactical(id);if(!tactical&&!id.equals("item.firstaid.bandage"))return;Object value=R.call(event,"getToolTip");if(!(value instanceof List<?>))return;@SuppressWarnings("unchecked")List<Object> lines=(List<Object>)value;Class<?> component=R.type("net.minecraft.network.chat.Component");Object name=R.call(component,"translatable",tactical?"firstaid.dressing.tactical":"firstaid.dressing.medical",new Object[0]);if(!lines.isEmpty())lines.set(0,name);lines.add(R.call(component,"translatable",tactical?"firstaid.dressing.tactical_boost":"firstaid.dressing.medical_boost",new Object[0]));}
 public static boolean lrBandage(Object player,Object stack,Object definition){String key=Objects.toString(R.call(definition,"getId"),"");if(!key.startsWith("lrtactical:")||!key.contains("bandage"))return false;if(R.yes(R.call(R.call(player,"level"),"isClientSide")))return true;Object model=Assist.model(player);if(model==null)return true;Object state=R.call(R.type("ichttt.mods.firstaid.survival.ClinicalData"),"state",model);int index=((Number)R.call(R.type("ichttt.mods.firstaid.compat.lrtactical.MedicalBridge"),"woundIndex",model,state,false)).intValue();if(index<0)return true;Object wound=((Object[])R.get(state,"wounds"))[index];if(!R.yes(R.call(wound,"bandage")))return true;R.call(R.type("ichttt.mods.firstaid.compat.lrtactical.TreatmentV33"),"applied",model,player,index,stack);Object[] parts=R.type("ichttt.mods.firstaid.api.enums.EnumPlayerPart").getEnumConstants();R.call(R.type("ichttt.mods.firstaid.fracture.Bleeding"),"stop",player,parts[index],true);R.call(model,"scheduleResync");R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"syncDamageModel",player);return true;}
}
